"""Frozen exploratory 3-EMA campaign. No L2, no protective holdout labels."""
from pathlib import Path, PureWindowsPath
import argparse,base64,zlib,json,hashlib,platform
from statistics import NormalDist
import numpy as np
import pandas as pd
import pyarrow.dataset as ds
import pyarrow.parquet as pq
NS=10**9;STEP=300*NS;HOLD=3600*NS;SEED=20261001;BOOT=20000
ASSETS=['MNQ','YM','RTY'];FAMILIES=['CROSS','SWEEP'];FILTERS=['BASE','DWELL30','SLOPE200','ADX25']
CATALOGS=json.loads(zlib.decompress(base64.b64decode("")))
EXPECTED=json.loads(zlib.decompress(base64.b64decode("")))
MANIFEST=json.loads(zlib.decompress(base64.b64decode("")))
DAYS=json.loads(zlib.decompress(base64.b64decode("eJxN0TESwjAMBMCvMKkprLMdzFsY/v8N3DDeVJvmrJM+V1pmtfa6no+/F34fV8MdDzzxjckPOSkcTH7IjznMGebs5PeTv3/wwBPf+LxVdN8fDiafnVSZs/CZudhJsZOie4U5c+ZMKxzc8cATL3zmCX1D39A39Aq9Qq9w03CjcKPsG31/AutzQQ==")))
FEES={'MNQ':2.4,'YM':.9,'RTY':.9} # Assumed roundtrip USD1.20/$0.50, USD4.50/$5.
def sha(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def dump(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False,allow_nan=False))
def scan(file,cols,lo,hi):
 return ds.dataset(file,format='parquet').scanner(columns=cols,filter=(ds.field('ts_utc_ns')>=lo)&(ds.field('ts_utc_ns')<hi),batch_size=250000,use_threads=False).to_batches()
def rma(x,n):
 a=np.asarray(x,float);o=np.full(len(a),np.nan);good=np.where(np.isfinite(a))[0]
 if len(good)<n:return o
 first=good[0];seed=first+n-1
 assert np.isfinite(a[first:]).all()
 o[seed]=a[first:seed+1].mean()
 for i in range(seed+1,len(a)):o[i]=o[i-1]+(a[i]-o[i-1])/n
 return o
def indicators(b):
 b=b.copy();c=b.c.astype(float)
 for n in [20,50,200]:b[f'e{n}']=c.ewm(span=n,adjust=False).mean()
 prev=c.shift().to_numpy();tr=np.maximum(b.h-b.l,np.maximum(abs(b.h-prev),abs(b.l-prev))).to_numpy(float)
 atr=rma(tr,14);up=b.h.diff().fillna(0).to_numpy();dn=(-b.l.diff()).fillna(0).to_numpy()
 plus=np.where((up>dn)&(up>0),up,0.);minus=np.where((dn>up)&(dn>0),dn,0.)
 plus[0]=minus[0]=np.nan
 with np.errstate(invalid='ignore',divide='ignore'):
  pdi=np.where(atr>0,100*rma(plus,14)/atr,np.where(np.isfinite(atr),0,np.nan));mdi=np.where(atr>0,100*rma(minus,14)/atr,np.where(np.isfinite(atr),0,np.nan))
  den=pdi+mdi;dx=np.where(den>0,100*abs(pdi-mdi)/den,np.where(np.isfinite(den),0,np.nan))
 b['adx']=rma(dx,14);b['atr_prev']=pd.Series(atr).shift().to_numpy();b['close_ns']=(b.bucket+1)*STEP
 et=pd.to_datetime(b.bucket*STEP,utc=True).dt.tz_convert('America/New_York');b['date']=et.dt.strftime('%Y%m%d');b['minute']=et.dt.hour*60+et.dt.minute
 return b
def make_events(b,asset,contract,selected_days):
 """Base schedule frozen first; filters are subsets, never reschedule rejected slots."""
 slots=[];blocked={f:-1 for f in FAMILIES}
 for i in range(600,len(b)):
  row=b.iloc[i];prev=b.iloc[i-1];day=row['date'];ns=int(row.close_ns)
  if day not in selected_days or row.minute<600 or row.minute+5>885:continue
  # No signal on an unobserved predecessor; EMA history uses real observed Globex bars.
  if row.bucket-prev.bucket!=1 or not np.isfinite(row.atr_prev) or row.atr_prev<=0:continue
  diff=row.e20-row.e50;pdiff=prev.e20-prev.e50
  cross=1 if pdiff<=0<diff and row.c>row.e200 else -1 if pdiff>=0>diff and row.c<row.e200 else 0
  sweep=1 if prev.e20>prev.e50>prev.e200 and prev.c>prev.e50 and row.l<=prev.e50-1 and row.c>prev.e50 else -1 if prev.e20<prev.e50<prev.e200 and prev.c<prev.e50 and row.h>=prev.e50+1 and row.c<prev.e50 else 0
  for family,side in [('CROSS',cross),('SWEEP',sweep)]:
   if not side or ns<=blocked[family]:continue
   # One-hour holding period +60s reserve, shared by all filtered versions.
   blocked[family]=ns+HOLD+60*NS
   six=b.iloc[i-6:i];consecutive=bool((np.diff(b.bucket.iloc[i-6:i+1])==1).all())
   dwell=consecutive and bool((side*(six.c-six.e50)>0).all())
   slope=bool(side*(prev.e200-b.e200.iloc[i-7])>0)
   adx=bool(np.isfinite(prev.adx) and prev.adx>=25)
   flags={'BASE':True,'DWELL30':dwell,'SLOPE200':slope,'ADX25':adx}
   ident=f'{asset}|{contract}|{day}|{family}|{ns}'
   cutoff=int(pd.Timestamp(f'{day} 16:00',tz='America/New_York').value)
   slots.append(dict(id=ident,asset=asset,contract=contract,day=day,family=family,signal_ns=ns,direction=side,U=float(row.atr_prev),filters=flags,cutoff_ns=cutoff,status='PENDING_ENTRY'))
 return slots

def aggregate_profile(file,ss):
 lo=min(s['start'] for s in ss)-7*86400*NS;hi=max(s['end'] for s in ss)
 bars={};counts={s['trade_date']:0 for s in ss};prof=dict(rows=0,nulls=0,invalid_quotes=0,time_ties=0,nonpositive_price_volume=0)
 last=None
 for batch in scan(file,['ts_utc_ns','price_ticks','volume','bid_ticks','ask_ticks'],lo,hi):
  t=batch.to_pandas()
  if t.empty:continue
  ts=t.ts_utc_ns.to_numpy()
  assert np.all(ts[1:]>=ts[:-1]) and (last is None or ts[0]>=last)
  prof['time_ties']+=int((ts[1:]==ts[:-1]).sum())+int(last is not None and ts[0]==last);last=int(ts[-1])
  prof['rows']+=len(t);prof['nulls']+=int(t.isna().sum().sum())
  prof['invalid_quotes']+=int((~((t.bid_ticks>0)&(t.ask_ticks>t.bid_ticks))).sum())
  prof['nonpositive_price_volume']+=int(((t.price_ticks<=0)|(t.volume<=0)).sum())
  assert not t[['ts_utc_ns','price_ticks','volume']].isna().any().any()
  assert (t.price_ticks>0).all() and (t.volume>0).all() and np.equal(t.price_ticks,np.floor(t.price_ticks)).all()
  for s in ss:counts[s['trade_date']]+=int(np.searchsorted(ts,s['end'],side='left')-np.searchsorted(ts,s['start'],side='left'))
  q=t.assign(bucket=t.ts_utc_ns//STEP).groupby('bucket',sort=True).agg(o=('price_ticks','first'),h=('price_ticks','max'),l=('price_ticks','min'),c=('price_ticks','last'),n=('price_ticks','size'))
  for bucket,row in q.iterrows():
   k=int(bucket);v=[float(row.o),float(row.h),float(row.l),float(row.c),int(row.n)]
   if k in bars:
    z=bars[k];bars[k]=[z[0],max(z[1],v[1]),min(z[2],v[2]),v[3],z[4]+v[4]]
   else:bars[k]=v
 for s in ss:assert counts[s['trade_date']]==s['ticks'],('CATALOG_ROWS',s['trade_date'],counts[s['trade_date']],s['ticks'])
 b=pd.DataFrame([(k,*v) for k,v in sorted(bars.items())],columns=['bucket','o','h','l','c','n'])
 prof.update(catalog_rows_reconciled=True,bars=len(b),warmup_lo_ns=lo,analysis_hi_ns=hi,timestamp_ties='distinct prints preserved, not deduplicated',null_quotes='invalid for execution; price/volume nulls fail closed')
 return indicators(b),prof,lo,hi

def resolve_quotes(slots,batches):
 """First observable valid quote after entry intent; no exit-lag exclusion of losers."""
 waiting={s['id']:s for s in slots};openpos={};stats={'invalid_quotes':0,'quote_rows':0}
 for batch in batches:
  t=batch.to_pandas()
  if t.empty:continue
  rawts=t.ts_utc_ns.to_numpy();last=int(rawts[-1]);valid=np.isfinite(t[['bid_ticks','ask_ticks']]).all(axis=1)&(t.bid_ticks>0)&(t.ask_ticks>t.bid_ticks)
  q=t.loc[valid];ts=q.ts_utc_ns.to_numpy();bid=q.bid_ticks.to_numpy(float);ask=q.ask_ticks.to_numpy(float)
  stats['invalid_quotes']+=int((~valid).sum());stats['quote_rows']+=len(q)
  for ident,s in list(waiting.items()):
   target=s['signal_ns']+250000000;deadline=s['signal_ns']+30*NS
   if last<=target:continue
   j=int(np.searchsorted(ts,target,side='right'))
   if j<len(ts) and ts[j]<=deadline:
    s.update(status='OPEN',entry_ns=int(ts[j]),entry_bid=float(bid[j]),entry_ask=float(ask[j]));openpos[ident]=s;del waiting[ident]
   elif last>deadline:s['status']='NO_ENTRY_QUOTE_WITHIN30S';del waiting[ident]
  for ident,s in list(openpos.items()):
   target=s['entry_ns']+HOLD
   if last<target:continue
   j=int(np.searchsorted(ts,target,side='left'))
   if j<len(ts) and ts[j]<=s['cutoff_ns']:
    d=s['direction'];eb=s['entry_bid'];ea=s['entry_ask'];xb=float(bid[j]);xa=float(ask[j]);gross=xb-ea if d>0 else eb-xa
    alpha=d*((xb+xa)-(eb+ea))/2;baseline=(gross+(eb-xa if d>0 else xb-ea))/2
    assert abs(alpha-(gross-baseline))<1e-9
    net=gross-2-FEES[s['asset']]
    s.update(status='COMPLETE',exit_ns=int(ts[j]),exit_bid=xb,exit_ask=xa,gross_ticks=gross,net_ticks=net,alpha_ticks=alpha,net_U=net/s['U'],alpha_U=alpha/s['U'],exit_lag_s=(int(ts[j])-target)/NS,entry_lag_s=(s['entry_ns']-s['signal_ns'])/NS,net_adverse_U=(net-2)/s['U'])
    del openpos[ident]
   elif last>s['cutoff_ns']:s['status']='UNKNOWN_EXIT_NO_QUOTE_BY16ET';del openpos[ident]
 for s in waiting.values():s['status']='NO_ENTRY_QUOTE_WITHIN30S'
 for s in openpos.values():s['status']='UNKNOWN_EXIT_EOF'
 return stats

def evaluate(slots,days,seed):
 unknown=sum(s['status'].startswith('UNKNOWN_EXIT') for s in slots);noentry=sum(s['status'].startswith('NO_ENTRY') for s in slots);rows=[s for s in slots if s['status']=='COMPLETE']
 out=dict(intents=len(slots),trades=len(rows),no_entry=noentry,unknown_exit=unknown,active_sessions=len({s['day'] for s in rows}),eligible_sessions=len(days))
 assert out['intents']==out['trades']+noentry+unknown
 if unknown:return dict(out,status='ABSTAIN_UNKNOWN_EXIT',net_U=None,net_ticks=None)
 if not rows:return dict(out,status='INCONCLUSIVE_SAMPLE',net_U=None,net_ticks=None)
 out.update(net_U=float(np.mean([s['net_U'] for s in rows])),alpha_U=float(np.mean([s['alpha_U'] for s in rows])),net_ticks=float(np.mean([s['net_ticks'] for s in rows])),net_U_per_session=sum(s['net_U'] for s in rows)/len(days),net_adverse_U=float(np.mean([s['net_adverse_U'] for s in rows])),max_exit_lag_s=max(s['exit_lag_s'] for s in rows))
 if len(rows)<30 or out['active_sessions']<20:return dict(out,status='INCONCLUSIVE_SAMPLE')
 a=np.array([[sum(s['net_U'] for s in rows if s['day']==d),sum(s['alpha_U'] for s in rows if s['day']==d),sum(s['day']==d for s in rows)] for d in days],float)
 rng=np.random.default_rng(seed);boot=[]
 for _ in range(20):
  sums=a[rng.integers(0,len(a),size=(BOOT//20,len(a)))].sum(axis=1);ok=sums[:,2]>0;boot.append(sums[ok,:2]/sums[ok,2,None])
 boot=np.vstack(boot);low=np.quantile(boot,.05/48,axis=0);se=boot.std(axis=0,ddof=1)
 out.update(lower_bonferroni_U=low.tolist(),mde80_U=((NormalDist().inv_cdf(1-.05/48)+NormalDist().inv_cdf(.8))*se).tolist(),status='SCREEN_PASS' if (low>0).all() else 'NO_SUPPORT')
 assert abs(out['net_U']-a[:,0].sum()/a[:,2].sum())<1e-9
 return out

def selftest():
 b=pd.DataFrame(dict(bucket=np.arange(900),o=np.arange(900,dtype=float)+1000,h=np.arange(900,dtype=float)+1001,l=np.arange(900,dtype=float)+999,c=np.arange(900,dtype=float)+1000,n=np.ones(900)))
 z=indicators(b);ref=[float(b.c.iloc[0])]
 for v in b.c.iloc[1:]:ref.append(ref[-1]+2/21*(v-ref[-1]))
 assert np.max(abs(z.e20.to_numpy()-np.array(ref)))<1e-9
 assert np.allclose(z.adx.dropna().tail(100),100)
 const=b.copy();const[['o','h','l','c']]=1000.;zc=indicators(const);assert np.allclose(zc.e200,1000) and np.allclose(zc.adx.dropna(),0)
 changed=b.copy();changed.loc[750:,'c']+=1e5;changed.loc[750:,'h']+=1e5;changed.loc[750:,'l']+=1e5;ch=indicators(changed)
 assert np.allclose(ch.e200[:750],z.e200[:750]) and np.allclose(ch.adx[30:750],z.adx[30:750])
 s=dict(id='x',asset='YM',signal_ns=0,direction=1,U=10.,cutoff_ns=7200*NS,status='PENDING_ENTRY')
 batches=[pd.DataFrame(dict(ts_utc_ns=[250000000,2*NS],bid_ticks=[99,100],ask_ticks=[101,102])),pd.DataFrame(dict(ts_utc_ns=[3610*NS],bid_ticks=[110],ask_ticks=[112]))]
 class Batch:
  def __init__(self,x):self.x=x
  def to_pandas(self):return self.x
 resolve_quotes([s],[Batch(x) for x in batches]);assert s['status']=='COMPLETE' and s['net_ticks']==5.1 and s['exit_lag_s']==8
 missing=dict(id='m',asset='YM',signal_ns=0,direction=1,U=10.,cutoff_ns=3700*NS,status='PENDING_ENTRY')
 resolve_quotes([missing],[Batch(batches[0]),Batch(pd.DataFrame(dict(ts_utc_ns=[3800*NS],bid_ticks=[1],ask_ticks=[2])))])
 assert missing['status'].startswith('UNKNOWN_EXIT');assert evaluate([missing],['d'],1)['status']=='ABSTAIN_UNKNOWN_EXIT'
 # Event-prefix stability on real clock fixture and synthetic sweep/cross seeds.
 bb=b.copy();bb['bucket']=pd.Timestamp('2025-10-06 17:00',tz='America/Chicago').value//STEP+np.arange(900);bb['c']=1000+20*np.sin(np.arange(900)/30);bb['h']=bb.c+10;bb['l']=bb.c-10;zz=indicators(bb);cut=int(zz.close_ns.iloc[780]);cc=bb.copy();cc.loc[781:,['c','h','l']]+=1000
 all_days=set(zz['date']);e1=make_events(zz,'YM','test',all_days);e2=make_events(indicators(cc),'YM','test',all_days)
 assert [e for e in e1 if e['signal_ns']<=cut]==[e for e in e2 if e['signal_ns']<=cut]
 return dict(status='PASS',checks='EMA independent recurrence; Wilder trend/flat; prefix indicators/events; delayed exit included; unknown exit abstention; costs')

def run(root,out):
 out.mkdir(parents=True,exist_ok=True);dump(out/'manifest.json',MANIFEST);dump(out/'selftests.json',selftest())
 auditpath=root/'AUDIT_MANIFEST.json';assert sha(auditpath)==EXPECTED['AUDIT_MANIFEST.json'];audit=json.load(open(auditpath));af={x['relative_path']:x for x in audit['files']}
 custody=[];files=[]
 for asset in ASSETS:
  cp=root/'catalogs'/f'{asset}_nt8_2025_2026q3_sessions_catalog.json';assert sha(cp)==EXPECTED['catalogs/'+cp.name];assert json.load(open(cp))==CATALOGS[asset]
  ss=[s for s in CATALOGS[asset]['sessions'] if s['trade_date'] in DAYS];assert len(ss)==len(DAYS)
  for name in sorted({PureWindowsPath(s['path']).name for s in ss}):
   rel=asset+'/'+name;f=root/rel;h=sha(f);meta=pq.ParquetFile(f).metadata
   assert h==EXPECTED[rel]==af[rel]['sha256'] and meta.num_rows==af[rel]['rows'] and f.stat().st_size==af[rel]['size_zstd_bytes']
   sub=[s for s in ss if PureWindowsPath(s['path']).name==name];files.append((asset,f,sub));custody.append(dict(path=rel,sha256=h,rows=meta.num_rows,bytes=f.stat().st_size))
 dump(out/'preflight.json',dict(script_sha256=sha(Path(__file__)),custody=custody,days=len(DAYS),l2_used=False,holdout_opened=False,validation_opened=False,python=platform.python_version()))
 allslots=[];profiles=[];replays=[]
 # Profile all files and form causal events BEFORE any real PNL is computed.
 for asset,f,ss in files:
  b,profile,lo,hi=aggregate_profile(f,ss);profile.update(asset=asset,path=f.name);profiles.append(profile)
  slots=make_events(b,asset,ss[0]['contract'],set(s['trade_date'] for s in ss));allslots.extend(slots);replays.append((f,lo,hi,slots));print('target-free',asset,f.name,'bars',len(b),'slots',len(slots),flush=True)
 dump(out/'profiles.json',profiles)
 for f,lo,hi,slots in replays:
  resolve_quotes(slots,scan(f,['ts_utc_ns','bid_ticks','ask_ticks'],lo,hi));print('replayed',f.name,len(slots),flush=True)
 assert len({s['id'] for s in allslots})==len(allslots)
 for asset in ASSETS:
  for fam in FAMILIES:
   rr=sorted([s for s in allslots if s['asset']==asset and s['family']==fam and s['status']=='COMPLETE'],key=lambda s:s['signal_ns'])
   assert all(a['exit_ns']<b['signal_ns'] for a,b in zip(rr,rr[1:])),('OVERLAP_EXECUTION',asset,fam)
 cells={};j=0
 for asset in ASSETS:
  for fam in FAMILIES:
   for filt in FILTERS:
    sel=[s for s in allslots if s['asset']==asset and s['family']==fam and s['filters'][filt]];key=f'{asset}_{fam}_{filt}';cells[key]=evaluate(sel,DAYS,SEED+j);j+=1
    base=[s for s in allslots if s['asset']==asset and s['family']==fam and s['status']=='COMPLETE'];good=[s for s in sel if s['status']=='COMPLETE']
    cells[key]['descriptive_delta_vs_base_U']=float(np.mean([s['net_U'] for s in good])-np.mean([s['net_U'] for s in base])) if good and base and not cells[key]['unknown_exit'] else None
 with open(out/'slots_PRIVATE.jsonl','w') as f:
  for s in allslots:f.write(json.dumps(s,ensure_ascii=False,allow_nan=False)+'\n')
 result=dict(cells=cells,days=len(DAYS),scope='EXPLORATORY_DEVELOPMENT_ONLY_NOT_LIVE',l2_used=False,holdout_opened=False,validation_opened=False,passes=[k for k,v in cells.items() if v['status']=='SCREEN_PASS'],limits=['3 correlated equity-index instruments, not independent replication','Exported quotes, age/fills not certified; costs assumed','Each filter is subset of same base slots, no rescheduling; delta descriptive only','No entry within30s is no trade, not zero return on a filled trade; any unknown exit blocks inference'])
 dump(out/'results.json',result);print('COMPLETE',len(cells),'cells','passes',result['passes'],flush=True)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--input');p.add_argument('--out',default='/kaggle/working/ema3');p.add_argument('--selftest',action='store_true');a=p.parse_args()
 if a.selftest:print(selftest())
 else:run(Path(a.input),Path(a.out))
